// TvFeedFeatured defines model for TvFeedFeatured.
type TvFeedFeatured struct {
	// D The data of the message
	D struct {
		// Fen The X-FEN of the current position
		Fen string `json:"fen"`

		// Id The game ID
		Id          string    `json:"id"`
		Orientation GameColor `json:"orientation"`
		Players     []struct {
			Color  GameColor `json:"color"`
			Rating int       `json:"rating"`

			// Seconds The player's remaining time in seconds
			Seconds int       `json:"seconds"`
			User    LightUser `json:"user"`
		} `json:"players"`
	} `json:"d"`

	// T The type of message.
	// A summary of the game is sent as the first message and when the featured game changes.
	// Subsequent messages are just the X-FEN, last move, and clocks.
	T TvFeedFeaturedT `json:"t"`
}

// TvFeedFeaturedT The type of message.
// A summary of the game is sent as the first message and when the featured game changes.
// Subsequent messages are just the X-FEN, last move, and clocks.
type TvFeedFeaturedT string

// TvFeedFen defines model for TvFeedFen.
type TvFeedFen struct {
	// D The data of the message
	D struct {
		// Bc Black's clock in seconds
		Bc int `json:"bc"`

		// Fen The X-FEN of the current position
		Fen string `json:"fen"`

		// Lm The last move in UCI format (King to rook for Chess960-compatible
		// castling notation)
		Lm string `json:"lm"`

		// Wc White's clock in seconds
		Wc int `json:"wc"`
	} `json:"d"`

	// T The type of message.
	// A summary of the game is sent as the first message and when the featured game changes.
	// Subsequent messages are just the X-FEN, last move, and clocks.
	T TvFeedFenT `json:"t"`
}

